from pathlib import Path
import base64,re,subprocess
R=Path(__file__).resolve().parents[2]; p=R/'index.html'; a=R/'assets/case-study-activity.jpg'
b=''''''
s=p.read_text(); s=s.replace('var caseMap={"Case Study Apple":"Case Study：Apple","ケーススタディ Apple":"ケーススタディ：Apple","案例研究 Apple":"案例研究：Apple"};','var caseMap={"Case Study Apple":"Case Study: APPLE","Case Study：Apple":"Case Study: APPLE","Case Study: Apple":"Case Study: APPLE","ケーススタディ Apple":"ケーススタディ：Apple","案例研究 Apple":"案例研究：Apple"};',1)
o='''    if(scope){scope.querySelectorAll("h1,h2,h3,.hierarchy-heading").forEach(function(el){patchTextNodes(el,caseMap);});}'''
n='''    if(scope){scope.querySelectorAll("h1,h2,h3,.hierarchy-heading").forEach(function(el){patchTextNodes(el,caseMap);});if(!scope.querySelector('img[data-case-study-activity="1"]')){var h=scope.querySelector('.ss-unified-heading[data-ss-section="capabilities"]');if(h){var i=document.createElement("img");i.src="assets/case-study-activity.jpg";i.alt="";i.loading="lazy";i.setAttribute("data-case-study-activity","1");i.style.cssText="display:block;width:100%;height:auto";h.insertAdjacentElement("afterend",i);}}}'''
if o not in s: raise SystemExit('apply target missing')
s=s.replace(o,n,1); p.write_text(s); a.parent.mkdir(exist_ok=True); a.write_bytes(base64.b64decode(b));
assert a.stat().st_size>12000 and a.read_bytes()[:2]==b'\xff\xd8'; assert 'Case Study: APPLE' in s and 'data-case-study-activity' in s
m=re.search(r'<script id="requested-home-copy-overrides">(.*?)</script>',s,re.S); q=R/'.case.js'; q.write_text(m.group(1)); subprocess.run(['node','--check',str(q)],check=True); q.unlink(); subprocess.run(['git','diff','--check'],cwd=R,check=True)
